edits.with:
#bpview .bpnote{font-size:13px;color:var(--ink-2);margin:6px 0 10px}
/* s85: blueprint as a responsive grid (a table collapsed into unlabeled cards on phones) */
#bpview .bpg{margin:10px 0 22px;font-family:var(--sans);font-size:13px;color:var(--ink)}
#bpview .bpcap{font-weight:800;font-size:11px;letter-spacing:1.2px;text-transform:uppercase;color:var(--muted);margin:0 0 6px}
#bpview .bpr{display:grid;grid-template-columns:minmax(0,1fr) repeat(6,minmax(58px,auto));gap:4px 12px;align-items:baseline;padding:8px 10px;border-bottom:1px solid rgba(0,0,0,.07)}
#bpview .bptask .bpr{grid-template-columns:minmax(0,1fr) repeat(3,minmax(70px,auto))}
#bpview .bphd{font-size:10px;font-weight:800;letter-spacing:.8px;text-transform:uppercase;color:var(--muted);border-bottom:1px solid rgba(0,0,0,.15)}
#bpview .bc{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
#bpview .bpr.bpgap .bn{color:#9A5B0E;font-weight:700}
#bpview .bpr.bpna{color:var(--muted)}
@media (max-width:640px){
  #bpview .bphd{display:none}
  #bpview .bpr,#bpview .bptask .bpr{grid-template-columns:repeat(3,minmax(0,1fr));gap:6px 10px;padding:10px 4px}
  #bpview .bn{grid-column:1/-1;font-weight:700;line-height:1.3}
  #bpview .bc{text-align:left;white-space:normal;font-size:14px}
  #bpview .bc::before{content:attr(data-l);display:block;font-size:9.5px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;color:var(--muted);margin-bottom:1px}
}

