function pct(r){ return r?r[0]+'\u2013'+r[1]+'%':'\u2014'; }
function blueprint(){
  var host=document.querySelector('#bpview .bptable'); if(!host) return;
  var shelf=(window.axShelf&&window.axShelf())||'step2';
  var cols=shelf==='peds'?['peds']:shelf==='fm'?['fm']:['peds','fm'];
  var rows={},tasks={dx:0,mgmt:0,found:0,review:0},total=0;
  Object.keys(OUT.codes).forEach(function(k){ rows[k]={p:0,s:0,q:0,n:0}; });
  document.querySelectorAll('.brief').forEach(function(b){
    if(b.style.display==='none') return;
    var bp=(b.getAttribute('data-bp')||'').split(/\s+/); if(!bp[0]||!rows[bp[0]]) return;
    rows[bp[0]].p++; if(bp[1]&&rows[bp[1]]) rows[bp[1]].s++;
    var qs=b.querySelectorAll('.mcq'); rows[bp[0]].q+=qs.length; rows[bp[0]].n+=nbmeIds(b).length;
    qs.forEach(function(m){ var qp=m.querySelector('.qp'); var t=OUT.type_to_task[(qp&&qp.dataset.type)||'']||'review'; tasks[t]++; total++; });
  });
  var h='<div class="tw"><table><caption>Coverage by NBME system</caption><thead><tr><th>System</th>'+
    cols.map(function(c){return '<th>'+(c==='peds'?'Peds share':'FM share')+'</th>';}).join('')+
    '<th>Briefs</th><th>Also in</th><th>Questions</th><th>NBME-linked</th></tr></thead><tbody>';
  Object.keys(OUT.codes).forEach(function(k){
    var inScope=cols.some(function(c){return OUT.weights[c][k];}); var r=rows[k];
    if(!inScope&&!r.p) return;
    var gap=inScope&&r.p===0;
    h+='<tr'+(gap?' class="bpgap"':'')+'><td>'+OUT.codes[k]+'</td>'+cols.map(function(c){return '<td>'+pct(OUT.weights[c][k])+'</td>';}).join('')+
      '<td>'+(r.p||'<b>0</b>')+'</td><td>'+r.s+'</td><td>'+r.q+'</td><td>'+r.n+'</td></tr>';
  });
  h+='</tbody></table></div>';
  var tk=cols[0], TN={dx:'Diagnosis',mgmt:'Management and health maintenance',found:'Foundational science',hm:'Health maintenance'};
  h+='<div class="tw"><table><caption>Questions by physician task</caption><thead><tr><th>Task</th><th>'+(tk==='peds'?'Peds share':'FM share')+'</th><th>Questions</th><th>Share here</th></tr></thead><tbody>';
  ['dx','mgmt','found','review'].forEach(function(t){
    var w=OUT.tasks[tk][t]||(t==='found'&&tk==='fm'?null:null);
    h+='<tr><td>'+(t==='review'?'Unassigned (claim)':TN[t])+'</td><td>'+(t==='review'?'\u2014':pct(w))+'</td><td>'+tasks[t]+'</td><td>'+(total?Math.round(100*tasks[t]/total)+'%':'\u2014')+'</td></tr>';
  });
  h+='</tbody></table></div>';
  host.innerHTML=h;
}

edits.with:
function pct(r){ return r?r[0]+'–'+r[1]+'%':'—'; }
function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;'); }
function bpRow(cls,name,cells){
  return '<div class="bpr'+(cls?' '+cls:'')+'" role="row"><span class="bn" role="rowheader">'+name+'</span>'+
    cells.map(function(c){ return '<span class="bc" role="cell" data-l="'+c[0]+'">'+c[1]+'</span>'; }).join('')+'</div>';
}
function bpHead(cols){ return '<div class="bpr bphd" role="row">'+cols.map(function(c,i){ return '<span class="'+(i?'bc':'bn')+'" role="columnheader">'+c+'</span>'; }).join('')+'</div>'; }
function blueprint(){
  var host=document.querySelector('#bpview .bptable'); if(!host) return;
  var shelf=(window.axShelf&&window.axShelf())||'step2';
  var O=BP[shelf]||BP.step2;
  var rows=O.rows.map(function(r){ return {r:r,p:0,s:0,q:0,n:0}; });
  var unl={r:{label:'Not in this outline',r:null},p:0,s:0,q:0,n:0,unl:1};
  function rowFor(code){ for(var i=0;i<rows.length;i++) if(rows[i].r.codes.indexOf(code)>-1) return rows[i];
    for(i=0;i<rows.length;i++) if(rows[i].r.rest) return rows[i]; return unl; }
  var tasks=O.tasks.map(function(t){ return {t:t,q:0}; }), tother={}, total=0;
  document.querySelectorAll('.brief').forEach(function(b){
    if(b.style.display==='none') return;
    var bp=(b.getAttribute('data-bp')||'').split(/\s+/); if(!bp[0]||!CODES[bp[0]]) return;
    var row=rowFor(bp[0]); row.p++;
    if(bp[1]&&CODES[bp[1]]){ var r2=rowFor(bp[1]); if(r2!==row) r2.s++; }
    var qs=b.querySelectorAll('.mcq'); row.q+=qs.length; row.n+=nbmeIds(b).length;
    qs.forEach(function(m){ var qp=m.querySelector('.qp'); var ty=(qp&&qp.dataset.type)||'claim'; total++;
      for(var i=0;i<tasks.length;i++) if(tasks[i].t.types && tasks[i].t.types.split(' ').indexOf(ty)>-1){ tasks[i].q++; return; }
      var k=ty==='mech'?'Foundational science (not a listed task on this exam)':ty==='claim'?'Unassigned (claim)':'Other ('+ty+')';
      tother[k]=(tother[k]||0)+1; });
  });
  function share(q){ return total?Math.round(100*q/total)+'%':'—'; }
  var h='<p class="bpnote bpsrc"><b>'+esc(O.name)+'</b> outline. Exam share is the published range; share here is this shelf’s questions in that row. A row in amber has no brief yet or sits below its range.'+(O.note?' '+esc(O.note):'')+'</p>';
  h+='<div class="bpg bpsys" role="table" aria-label="Coverage by system, '+esc(O.name)+'"><div class="bpcap">Coverage by system</div>'+
     bpHead(['System',O.share,'Briefs','Also in','Questions','Share here','NBME-linked']);
  rows.concat(unl.p?[unl]:[]).forEach(function(x){
    var sh=total?100*x.q/total:0, gap=!x.unl&&(x.p===0||(total&&x.r.r&&sh<x.r.r[0]));
    h+=bpRow(gap?'bpgap':'',esc(x.r.label),[[O.share,pct(x.r.r)],['Briefs',x.p||'<b>0</b>'],['Also in',x.s],['Questions',x.q],['Share here',share(x.q)],['NBME-linked',x.n]]);
  });
  h+='</div><div class="bpg bptask" role="table" aria-label="Questions by physician task, '+esc(O.name)+'"><div class="bpcap">Questions by physician task</div>'+
     bpHead(['Task',O.share,'Questions','Share here']);
  tasks.forEach(function(x){ h+=bpRow(x.t.types?'':'bpna',esc(x.t.label),[[O.share,pct(x.t.r)],['Questions',x.t.types?x.q:'not tagged'],['Share here',x.t.types?share(x.q):'—']]); });
  Object.keys(tother).forEach(function(k){ h+=bpRow('bpna',esc(k),[[O.share,'—'],['Questions',tother[k]],['Share here',share(tother[k])]]); });
  h+='</div>';
  host.innerHTML=h;
}
